  var BAD = /(signature|autograph|logo|coat of arms|blason|map|stamp|timbre|grave|tombe|plaque|\.svg|\.gif|\.tiff?)/i;
  var strip = (s) => String(s || "").replace(/<[^>]+>/g, "").replace(/&[a-z#0-9]+;/gi, " ").trim();
